SELECT FACTORY_CODE AS factoryCode, MATERIAL_CODE AS materialCode, CLASS3_LH_TYPE AS lhType, SUM(IFNULL(CLASS3_PLAN_QTY, 0) + IFNULL(CLASS4_PLAN_QTY, 0) + IFNULL(CLASS5_PLAN_QTY, 0)) AS dayPlanQty FROM T_LH_SCHEDULE_RESULT WHERE IS_DELETE = 0 AND FACTORY_CODE = #{factoryCode} AND DATE_FORMAT(SCHEDULE_DATE, '%Y-%m-%d') = DATE_FORMAT(#{finishDate}, '%Y-%m-%d') AND MATERIAL_CODE IN
#{code}
AND CLASS3_LH_TYPE IS NOT NULL GROUP BY FACTORY_CODE, MATERIAL_CODE, CLASS3_LH_TYPE
